package cn.balltv.portal;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class ExtraSourcesTest {
 @Test public void kqtGroupsRoomsByEventButKeepsUnlinkedRoomSeparate()throws Exception{JSONObject events=new JSONObject("{list:[{matchId:12,homeName:'甲',awayName:'乙',matchType:1,matchTime:'2026-01-01 15:00:00'}]}");JSONObject rooms=new JSONObject("{list:[{roomId:4,matchId:12,state:1,nickName:'A'},{roomId:5,matchId:12,state:1,nickName:'B'},{roomId:8,state:1,title:'桌球直播'},{roomId:9,matchId:13,state:0}]}");List<Feeds.Match> list=ExtraSources.parseKqt(events,rooms,"live");assertEquals(2,list.size());assertEquals(2,list.get(0).raw.getJSONObject("extra").getJSONArray("rooms").length());assertEquals("room:8",list.get(1).id);assertEquals("甲",list.get(0).home);}
 @Test public void kqtFutureGameIsNotClaimedAsLive()throws Exception{JSONObject events=new JSONObject("{list:[{matchId:12,homeName:'甲',awayName:'乙',matchTime:'2099-01-01 12:00:00'}]}");JSONObject rooms=new JSONObject("{list:[{roomId:4,matchId:12,state:1}]}");List<Feeds.Match> live=ExtraSources.parseKqt(events,rooms,"live");assertEquals(0,LiveState.admit(live,System.currentTimeMillis()).size());assertEquals("upcoming",ExtraSources.parseKqt(events,rooms,"schedule").get(0).status);}
 @Test public void somiSharesSchemaButRetainsDistinctSourceAndFiltersAds()throws Exception{JSONObject events=new JSONObject("{list:[{matchId:12,homeName:'甲',awayName:'乙',matchTime:'2026-01-01 15:00:00'}]}");JSONObject rooms=new JSONObject("{list:[{roomId:4,matchId:12,state:1},{roomId:5,state:1,title:'充值福利'},{roomId:6,state:1,isForceLogin:1},{roomId:7,state:1,title:'比赛回放'}]}");List<Feeds.Match> list=ExtraSources.parseSite(ExtraSources.SOMI,events,rooms,"live");assertEquals(1,list.size());assertEquals(ExtraSources.SOMI,list.get(0).source);}
}
